nual Average CPI-U: {cpi_1953}\")\n\n# Inflation adjustment factor\ninflation_factor = cpi_1953 / cpi_1940\nprint(f\"\\nInflation Factor (1953/1940): {inflation_factor:.6f}\")\n\n# Adjust 1940 expenditures to 1953 dollars\nsum_1940_adjusted = sum_1940 * inflation_factor\nprint(f\"\\n=== Inflation Adjustment ===\")\nprint(f\"1940 Total Adjusted to 1953 dollars: ${sum_1940_adjusted:,.2f} million\")\n\n# Calculate absolute difference\nabsolute_difference = abs(sum_1953 - sum_1940_adjusted)\n\nprint(f\"\\n=== Final Result ===\")\nprint(f\"1953 Total (nominal): ${sum_1953:,} million\")\nprint(f\"1940 Total (adjusted to 1953 dollars): ${sum_1940_adjusted:,.2f} million\")\nprint(f\"Absolute Difference: ${absolute_difference:,.2f} million\")\nprint(f\"\\nRounded to nearest hundredths: ${absolute_difference:.2f}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
